// Session Timeout Warning Component
// Land Intelligence System
// Shows a warning when session is about to expire

import React, { useState, useEffect } from 'react';
import { AlertTriangle, RefreshCw } from 'lucide-react';
import { useAuth } from '../store/authStore';
import { LoadingSpinner } from '@/components/ui/LoadingSpinner';

interface SessionTimeoutWarningProps {
  /** Time in minutes before token expiry to show warning */
  warningMinutes?: number;
  /** Auto-refresh enabled */
  autoRefresh?: boolean;
}

export const SessionTimeoutWarning: React.FC<SessionTimeoutWarningProps> = ({
  warningMinutes = 5,
  autoRefresh = true,
}) => {
  const { state, refreshAccessToken, logout } = useAuth();
  const [showWarning, setShowWarning] = useState(false);
  const [isRefreshing, setIsRefreshing] = useState(false);
  const [timeRemaining, setTimeRemaining] = useState<number | null>(null);

  useEffect(() => {
    if (!state.accessToken) {
      setShowWarning(false);
      return;
    }

    // Try to get token expiry from the token itself (JWT)
    const getTokenExpiry = (): number | null => {
      try {
        const payload = JSON.parse(atob(state.accessToken!.split('.')[1]));
        return payload.exp ? payload.exp * 1000 : null; // Convert to milliseconds
      } catch {
        return null;
      }
    };

    const expiry = getTokenExpiry();
    if (!expiry) return;

    const checkExpiry = () => {
      const now = Date.now();
      const remaining = expiry - now;
      const warningThreshold = warningMinutes * 60 * 1000;

      if (remaining <= warningThreshold && remaining > 0) {
        setShowWarning(true);
        setTimeRemaining(Math.floor(remaining / 1000)); // in seconds
      } else {
        setShowWarning(false);
      }
    };

    checkExpiry();
    const interval = setInterval(checkExpiry, 1000);

    return () => clearInterval(interval);
  }, [state.accessToken, warningMinutes]);

  // Auto-refresh when warning shows
  useEffect(() => {
    if (showWarning && autoRefresh && !isRefreshing) {
      const handleAutoRefresh = async () => {
        setIsRefreshing(true);
        try {
          await refreshAccessToken();
        } catch (error) {
          console.error('Session refresh failed:', error);
        } finally {
          setIsRefreshing(false);
        }
      };
      
      // Attempt refresh immediately when warning shows
      handleAutoRefresh();
    }
  }, [showWarning, autoRefresh, refreshAccessToken, isRefreshing]);

  if (!showWarning) return null;

  const formatTime = (seconds: number): string => {
    const mins = Math.floor(seconds / 60);
    const secs = seconds % 60;
    return `${mins}:${secs.toString().padStart(2, '0')}`;
  };

  return (
    <div className="fixed top-16 right-4 z-50 max-w-sm w-full">
      <div className="rounded-xl border border-warning/30 bg-warning/10 p-4 shadow-2xl backdrop-blur-sm">
        <div className="flex items-start gap-3">
          <AlertTriangle className="w-5 h-5 text-warning flex-shrink-0 mt-0.5" />
          <div className="flex-1">
            <h3 className="text-sm font-semibold text-warning">Session Expiring</h3>
            <p className="text-xs text-slate-300 mt-1">
              Your session will expire in {timeRemaining ? formatTime(timeRemaining) : 'a few minutes'}.
            </p>
            <div className="flex gap-2 mt-3">
              <button
                onClick={async () => {
                  setIsRefreshing(true);
                  try {
                    await refreshAccessToken();
                    setShowWarning(false);
                  } finally {
                    setIsRefreshing(false);
                  }
                }}
                disabled={isRefreshing}
                className="flex items-center gap-1.5 px-3 py-1.5 text-xs font-medium text-white bg-primary-600 rounded-lg hover:bg-primary-700 disabled:opacity-50 transition-colors"
              >
                {isRefreshing ? <LoadingSpinner size="sm" /> : <RefreshCw className="w-3 h-3" />}
                Refresh Session
              </button>
              <button
                onClick={logout}
                className="px-3 py-1.5 text-xs font-medium text-slate-300 bg-slate-800 rounded-lg hover:bg-slate-700 transition-colors"
              >
                Log Out
              </button>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
};

export default SessionTimeoutWarning;

// Login Page
// Land Intelligence System

import { useNavigate, useLocation } from 'react-router-dom';
import { useForm } from 'react-hook-form';
import { useAuth } from '../store/authStore';
import type { LoginCredentials } from '../types/auth';

export const LoginPage: React.FC = () => {
  const { login, state } = useAuth();
  const navigate = useNavigate();
  const location = useLocation();
  
  const {
    register,
    handleSubmit,
    formState: { errors },
  } = useForm<LoginCredentials>();

  const onSubmit = async (data: LoginCredentials) => {
    await login(data);
    if (state.isAuthenticated) {
      // Redirect to the page the user was trying to access, or home
      const from = (location.state as any)?.from?.pathname || '/';
      navigate(from, { replace: true });
    }
  };

  const inputClasses = 'appearance-none rounded-none relative block w-full px-3 py-2 border border-slate-700 placeholder-slate-500 text-white rounded-md focus:outline-none focus:ring-primary-500 focus:border-primary-500 focus:z-10 sm:text-sm bg-slate-800/50';

  return (
    <form className="mt-8 space-y-6" onSubmit={handleSubmit(onSubmit)}>
      <div className="rounded-md shadow-sm -space-y-px">
        <div>
          <label htmlFor="username" className="sr-only">
            Username
          </label>
          <input
            {...register('username', { required: 'Username is required' })}
            type="text"
            id="username"
            className={inputClasses}
            placeholder="Username"
          />
          {errors.username && (
            <p className="mt-1 text-sm text-red-400">{errors.username.message}</p>
          )}
        </div>
        <div>
          <label htmlFor="password" className="sr-only">
            Password
          </label>
          <input
            {...register('password', { required: 'Password is required' })}
            type="password"
            id="password"
            className={inputClasses}
            placeholder="Password"
          />
          {errors.password && (
            <p className="mt-1 text-sm text-red-400">{errors.password.message}</p>
          )}
        </div>
      </div>

      {state.error && (
        <div className="rounded-md bg-danger/10 p-4">
          <p className="text-sm text-danger">{state.error}</p>
        </div>
      )}

      <div>
        <button
          type="submit"
          disabled={state.isLoading}
          className="group relative w-full flex justify-center py-2 px-4 border border-transparent text-sm font-medium rounded-lg text-white bg-primary-600 hover:bg-primary-500 focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-primary-500 focus:ring-offset-slate-900 disabled:opacity-50 disabled:cursor-not-allowed transition-colors"
        >
          {state.isLoading ? 'Signing in...' : 'Sign in'}
        </button>
      </div>
    </form>
  );
};

export default LoginPage;

// Authentication Store
// Land Intelligence System

import { create } from 'zustand';
import { persist } from 'zustand/middleware';
import { authService } from '@/services/authService';
import { userService } from '@/services/userService';
import { LOCAL_STORAGE_KEYS } from '@/utils/constants';
import { ApiError } from '@/api/axios';
import type { LoginCredentials } from '../types/auth';
import type { UserResponse, UserRole } from '@/types/user';

// Role hierarchy: admin > client > viewer
const ROLE_HIERARCHY: Record<UserRole, number> = {
  admin: 3,
  client: 2,
  viewer: 1,
};

// Auth state interface
export interface AuthState {
  user: UserResponse | null;
  accessToken: string | null;
  refreshToken: string | null;
  isAuthenticated: boolean;
  isLoading: boolean;
  error: string | null;
  initializeFromStorage: () => void;
  setupUnauthorizedListener: () => () => void;
  login: (credentials: LoginCredentials) => Promise<boolean>;
  logout: () => void;
  refreshAccessToken: () => Promise<void>;
  fetchCurrentUser: () => Promise<void>;
  hasRole: (role: UserRole) => boolean;
  hasAnyRole: (roles: UserRole[]) => boolean;
}

// Create the store with middleware
// Use any cast to work around zustand persist middleware typing incompatibility
// eslint-disable-next-line @typescript-eslint/no-explicit-any
export const useAuthStore: any = create(
  // @ts-ignore
  persist(
    (set: (partial: Partial<AuthState>) => void, get: () => AuthState) => ({
      // Initial state
      user: null,
      accessToken: null,
      refreshToken: null,
      isAuthenticated: false,
      isLoading: false,
      error: null,

      initializeFromStorage: () => {
        const token = localStorage.getItem(LOCAL_STORAGE_KEYS.ACCESS_TOKEN);
        const refreshTokenVal = localStorage.getItem(LOCAL_STORAGE_KEYS.REFRESH_TOKEN);
        const userProfile = localStorage.getItem(LOCAL_STORAGE_KEYS.USER_PROFILE);

        if (token && refreshTokenVal && userProfile) {
          try {
            const user = JSON.parse(userProfile) as UserResponse;
            set({
              user,
              accessToken: token,
              refreshToken: refreshTokenVal,
              isAuthenticated: true,
            });
          } catch {
            console.error('Failed to parse user profile');
            get().logout();
          }
        }
      },

      setupUnauthorizedListener: () => {
        const handleUnauthorized = () => {
          set({
            user: null,
            accessToken: null,
            refreshToken: null,
            isAuthenticated: false,
            error: 'Session expired. Please log in again.',
          });
        };

        window.addEventListener('auth:unauthorized', handleUnauthorized);
        return () => window.removeEventListener('auth:unauthorized', handleUnauthorized);
      },

      login: async (credentials: LoginCredentials) => {
        set({ isLoading: true, error: null });
        try {
          const response = await authService.login(credentials);

          if (response.success && response.data) {
            const { access_token, refresh_token, user } = response.data;

            localStorage.setItem(LOCAL_STORAGE_KEYS.ACCESS_TOKEN, access_token);
            localStorage.setItem(LOCAL_STORAGE_KEYS.REFRESH_TOKEN, refresh_token);
            localStorage.setItem(LOCAL_STORAGE_KEYS.USER_PROFILE, JSON.stringify(user));

            set({
              user,
              accessToken: access_token,
              refreshToken: refresh_token,
              isAuthenticated: true,
              isLoading: false,
            });
            return true;
          } else {
            throw new Error(response.message || 'Login failed');
          }
        } catch (error) {
          const message = error instanceof ApiError
            ? error.message
            : (error as Error).message || 'Login failed';
          set({ error: message, isLoading: false, isAuthenticated: false });
          return false;
        }
      },

      logout: () => {
        const currentToken = get().accessToken;
        if (currentToken) {
          authService.logout().catch(() => {});
        }

        localStorage.removeItem(LOCAL_STORAGE_KEYS.ACCESS_TOKEN);
        localStorage.removeItem(LOCAL_STORAGE_KEYS.REFRESH_TOKEN);
        localStorage.removeItem(LOCAL_STORAGE_KEYS.USER_PROFILE);

        set({
          user: null,
          accessToken: null,
          refreshToken: null,
          isAuthenticated: false,
          error: null,
        });
      },

      refreshAccessToken: async () => {
        const refreshTokenValue = get().refreshToken;
        if (!refreshTokenValue) return;

        try {
          const response = await authService.refresh(refreshTokenValue);

          if (response.success && response.data) {
            const { access_token, refresh_token, user } = response.data;

            localStorage.setItem(LOCAL_STORAGE_KEYS.ACCESS_TOKEN, access_token);
            localStorage.setItem(LOCAL_STORAGE_KEYS.REFRESH_TOKEN, refresh_token);
            localStorage.setItem(LOCAL_STORAGE_KEYS.USER_PROFILE, JSON.stringify(user));

            set({
              user,
              accessToken: access_token,
              refreshToken: refresh_token,
            });
          }
        } catch {
          get().logout();
        }
      },

      fetchCurrentUser: async () => {
        set({ isLoading: true });
        try {
          const user = get().user;
          if (!user?.id) {
            set({ isLoading: false });
            return;
          }

          const response = await userService.getUserById(user.id);

          if (response.success && response.data) {
            localStorage.setItem(LOCAL_STORAGE_KEYS.USER_PROFILE, JSON.stringify(response.data));
            set({ user: response.data, isLoading: false });
          }
        } catch {
          set({ isLoading: false });
        }
      },

      hasRole: (role: UserRole): boolean => {
        const user = get().user;
        if (!user) return false;
        return user.role === role;
      },

      hasAnyRole: (roles: UserRole[]): boolean => {
        const user = get().user;
        if (!user) return false;
        const userRole = user.role as UserRole;
        const userRoleLevel = ROLE_HIERARCHY[userRole];
        return roles.some(role => ROLE_HIERARCHY[role] <= userRoleLevel);
      },
    }),
    {
      name: 'land-intelligence-auth',
      partialize: (state: AuthState) => ({
        user: state.user,
        accessToken: state.accessToken,
        refreshToken: state.refreshToken,
        isAuthenticated: state.isAuthenticated,
      }),
    }
  )
);

// Main hook for useAuth
export const useAuth = () => {
  const user = useAuthStore((state: AuthState) => state.user);
  const accessToken = useAuthStore((state: AuthState) => state.accessToken);
  const refreshToken = useAuthStore((state: AuthState) => state.refreshToken);
  const isAuthenticated = useAuthStore((state: AuthState) => state.isAuthenticated);
  const isLoading = useAuthStore((state: AuthState) => state.isLoading);
  const error = useAuthStore((state: AuthState) => state.error);
  const login = useAuthStore((state: AuthState) => state.login);
  const logout = useAuthStore((state: AuthState) => state.logout);
  const refreshAccessToken = useAuthStore((state: AuthState) => state.refreshAccessToken);
  const fetchCurrentUser = useAuthStore((state: AuthState) => state.fetchCurrentUser);
  const hasRole = useAuthStore((state: AuthState) => state.hasRole);
  const hasAnyRole = useAuthStore((state: AuthState) => state.hasAnyRole);

  return {
    state: {
      user,
      accessToken,
      refreshToken,
      isAuthenticated,
      isLoading,
      error,
    },
    login,
    logout,
    refreshAccessToken,
    fetchCurrentUser,
    hasRole,
    hasAnyRole,
  };
};

// Convenience hooks for role-based access
export const useUser = () => useAuthStore((state: AuthState) => state.user);
export const useAccessToken = () => useAuthStore((state: AuthState) => state.accessToken);
export const useRefreshToken = () => useAuthStore((state: AuthState) => state.refreshToken);
export const useAuthLoading = () => useAuthStore((state: AuthState) => state.isLoading);
export const useAuthError = () => useAuthStore((state: AuthState) => state.error);
export const useAuthStatus = () => {
  const isAuthenticated = useAuthStore((state: AuthState) => state.isAuthenticated);
  const user = useAuthStore((state: AuthState) => state.user);

  return {
    isAuthenticated,
    user,
    isLoading: useAuthStore((state: AuthState) => state.isLoading),
    hasRole: useAuthStore((state: AuthState) => state.hasRole),
    hasAnyRole: useAuthStore((state: AuthState) => state.hasAnyRole),
  };
};
export const useUserRole = () => useAuthStore((state: AuthState) => state.user?.role);
export const useIsAuthenticated = () => useAuthStore((state: AuthState) => state.isAuthenticated);

